  var checklistToastState={timer:0,lastKey:'',lastAt:0,lastSeverity:0};
  function checklistToast(type,title,message,sticky){
    type=String(type||'info').toLowerCase();
    if(['success','warning','error','info'].indexOf(type)<0)type='info';
    title=String(title||'Thông báo').trim()||'Thông báo';
    message=String(message||'').replace(/\s+/g,' ').trim();
    if(!message)message='Hệ thống chưa nhận được nội dung chi tiết. Vui lòng thực hiện lại thao tác hoặc tải lại trang.';
    var severity={info:1,success:2,warning:3,error:4}[type]||1;
    var now=Date.now(),toastKey=(type+'|'+title+'|'+message).toLowerCase();
    var host=document.querySelector('[data-phfck-toast-host]');
    if(!host){host=document.createElement('div');host.className='phfck-toast-host';host.setAttribute('data-phfck-toast-host','');document.body.appendChild(host);}
    var current=host.querySelector('.phfck-toast');
    if(current&&checklistToastState.lastKey===toastKey&&now-checklistToastState.lastAt<1400){
      checklistToastState.lastAt=now;
      return current;
    }
    if(current&&now-checklistToastState.lastAt<1600&&severity<checklistToastState.lastSeverity){
      return current;
    }
    if(checklistToastState.timer){clearTimeout(checklistToastState.timer);checklistToastState.timer=0;}
    host.querySelectorAll('.phfck-toast').forEach(function(oldToast){oldToast.classList.remove('is-visible');oldToast.remove();});
    var toast=document.createElement('div');
    toast.className='phfck-toast is-'+type;
    toast.setAttribute('role',type==='error'?'alert':'status');
    toast.setAttribute('aria-live',type==='error'?'assertive':'polite');
    toast.setAttribute('data-toast-key',toastKey);
    var icons={success:'✓',warning:'!',error:'×',info:'i'};
    toast.innerHTML='<span class="phfck-toast-icon">'+(icons[type]||'i')+'</span><div class="phfck-toast-copy"><b>'+esc(title)+'</b><p>'+esc(message)+'</p></div><button type="button" aria-label="Đóng thông báo">×</button><span class="phfck-toast-progress"></span>';
    host.appendChild(toast);
    checklistToastState.lastKey=toastKey;checklistToastState.lastAt=now;checklistToastState.lastSeverity=severity;
    requestAnimationFrame(function(){toast.classList.add('is-visible');});
    var closed=false;
    var duration={success:3200,info:4200,warning:5200,error:6500}[type]||4200;
    var remaining=duration,startedAt=0;
    var close=function(){if(closed)return;closed=true;if(checklistToastState.timer){clearTimeout(checklistToastState.timer);checklistToastState.timer=0;}toast.classList.remove('is-visible');setTimeout(function(){if(toast.parentNode)toast.remove();},180);};
    var scheduleClose=function(delay){if(closed)return;if(checklistToastState.timer)clearTimeout(checklistToastState.timer);remaining=Math.max(300,Number(delay)||duration);startedAt=Date.now();checklistToastState.timer=setTimeout(close,remaining);};
    toast.querySelector('button').addEventListener('click',close);
    toast.addEventListener('mouseenter',function(){if(closed||!checklistToastState.timer)return;clearTimeout(checklistToastState.timer);checklistToastState.timer=0;remaining=Math.max(300,remaining-(Date.now()-startedAt));toast.classList.add('is-paused');});
    toast.addEventListener('mouseleave',function(){if(closed)return;toast.classList.remove('is-paused');scheduleClose(remaining);});
    toast.addEventListener('focusin',function(){if(closed||!checklistToastState.timer)return;clearTimeout(checklistToastState.timer);checklistToastState.timer=0;remaining=Math.max(300,remaining-(Date.now()-startedAt));toast.classList.add('is-paused');});
    toast.addEventListener('focusout',function(){if(closed)return;toast.classList.remove('is-paused');scheduleClose(remaining);});
    scheduleClose(duration);
    return toast;
  }
  var legacyPhfNotice=window.phfNotice;
  window.phfNotice=function(message){
    if(document.querySelector('#phfChecklistRoot')){
      var text=String(message||'').trim(),type=/^Đã\b/i.test(text)?'success':(/^(Không|Chưa|Vui lòng|Cần)\b/i.test(text)?'warning':'info');
      return checklistToast(type,type==='success'?'Thao tác thành công':(type==='warning'?'Cần kiểm tra':'Thông báo'),text,type==='warning');
    }
    if(typeof legacyPhfNotice==='function')return legacyPhfNotice.apply(window,arguments);
  };


  var phfckDecisionState={active:false};
  function phfckDecisionModal(options){
    options=options||{};
    if(phfckDecisionState.active)return Promise.resolve(options.mode==='prompt'?null:false);
    var root=document.getElementById('phfChecklistRoot');
    if(!root)return Promise.resolve(options.mode==='prompt'?null:false);
    phfckDecisionState.active=true;
    var mode=options.mode==='prompt'?'prompt':'confirm',tone=options.tone==='danger'?'danger':(options.tone==='warning'?'warning':'normal');
    var title=String(options.title||'Xác nhận thao tác'),message=String(options.message||''),confirmText=String(options.confirmText||'Xác nhận'),cancelText=String(options.cancelText||'Hủy');
    var value=String(options.defaultValue||''),placeholder=String(options.placeholder||''),minLength=Math.max(0,Number(options.minLength)||0);
    return new Promise(function(resolve){
      var layer=document.createElement('div');
      layer.className='phfck-modal-layer phfck-decision-layer';layer.setAttribute('data-phfck-modal-layer','');layer.setAttribute('data-phfck-decision-layer','');
      layer.innerHTML='<div class="phfck-modal phfck-decision-modal phfck-official-modal is-'+tone+'" role="dialog" aria-modal="true" aria-labelledby="phfckDecisionTitle">'
        +'<div class="phfck-modal-head"><div><small>'+(tone==='danger'?'THAO TÁC CẦN CẨN TRỌNG':'XÁC NHẬN THAO TÁC')+'</small><h2 id="phfckDecisionTitle">'+esc(title)+'</h2><p>'+esc(message)+'</p></div><button type="button" data-phfck-decision-cancel aria-label="Đóng">×</button></div>'
        +'<div class="phfck-modal-body">'+(mode==='prompt'?'<label class="phfck-decision-input"><b>'+esc(options.inputLabel||'Lý do')+' <em>*</em></b><textarea rows="4" data-phfck-decision-value placeholder="'+esc(placeholder)+'">'+esc(value)+'</textarea><small>'+(minLength?'Tối thiểu '+minLength+' ký tự.':'Vui lòng nhập nội dung rõ ràng.')+'</small><p class="phfck-inline-error" data-phfck-decision-error hidden></p></label>':'<div class="phfck-decision-note"><span>'+(tone==='danger'?'!':'✓')+'</span><div><b>'+esc(options.noteTitle||'Vui lòng kiểm tra trước khi tiếp tục')+'</b><p>'+esc(options.note||'Hệ thống chỉ thực hiện sau khi anh xác nhận.')+'</p></div></div>')+'</div>'
        +'<div class="phfck-modal-foot"><button type="button" class="phfck-secondary" data-phfck-decision-cancel>'+esc(cancelText)+'</button><button type="button" class="'+(tone==='danger'?'phfck-danger':'phfck-primary')+'" data-phfck-decision-confirm>'+esc(confirmText)+'</button></div></div>';
      var decisionReturnFocus=document.activeElement,decisionParentLayer=topChecklistModalLayer();
      if(decisionParentLayer){decisionParentLayer.classList.add('is-phfck-modal-suspended');decisionParentLayer.setAttribute('data-phfck-modal-suspended','');try{decisionParentLayer.inert=true;}catch(_eSuspend){}}
      root.appendChild(layer);prepareChecklistModalLayer(layer,decisionReturnFocus);syncChecklistModalScrollLock();
      var input=layer.querySelector('[data-phfck-decision-value]'),confirmBtn=layer.querySelector('[data-phfck-decision-confirm]');
      function finish(result){if(!phfckDecisionState.active)return;phfckDecisionState.active=false;var returnFocus=layer.__phfckReturnFocus;layer.remove();if(decisionParentLayer&&decisionParentLayer.isConnected){decisionParentLayer.classList.remove('is-phfck-modal-suspended');decisionParentLayer.removeAttribute('data-phfck-modal-suspended');try{decisionParentLayer.inert=false;}catch(_eResume){}}syncChecklistModalScrollLock();requestAnimationFrame(function(){restoreChecklistModalFocus({__phfckReturnFocus:returnFocus});});resolve(result);}
      layer.querySelectorAll('[data-phfck-decision-cancel]').forEach(function(btn){btn.addEventListener('click',function(){finish(mode==='prompt'?null:false);});});
      confirmBtn.addEventListener('click',function(){
        if(mode==='prompt'){
          var text=String(input&&input.value||'').trim(),err=layer.querySelector('[data-phfck-decision-error]');
          if(text.length<minLength){if(err){err.hidden=false;err.textContent='Nội dung cần tối thiểu '+minLength+' ký tự.';}if(input)input.focus();return;}
          finish(text);return;
        }
        finish(true);
      });
      layer.addEventListener('keydown',function(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();finish(mode==='prompt'?null:false);}else if(e.key==='Enter'&&mode==='confirm'){e.preventDefault();e.stopPropagation();confirmBtn.click();}});
      requestAnimationFrame(function(){if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length);}else confirmBtn.focus();});
    });
  }
  function phfckConfirm(options){options=options||{};options.mode='confirm';return phfckDecisionModal(options);}
  function phfckPrompt(options){options=options||{};options.mode='prompt';return phfckDecisionModal(options);}

  var violationUiState={employeeId:'',selectedEmployee:null,templateId:'',step:1,evidenceRequired:false,duplicateWarning:true,mode:'quick',query:'',group:'all',expandedGroups:{},selected:{},date:'',location:'',department:'all',branch:'all',moreFiltersOpen:false,employeeQuery:'',employeeChanging:false,employeeSearchReady:false,employeeSelectionToken:0,employeeSelectionStatus:'idle',sharedNote:'',sharedEvidence:false,multiRows:[],lateRows:[],detailCriterionId:'',detailNote:'',detailTime:'',detailEvidenceNote:'',detailDraftSavedAt:'',evidence:{},quickPersonMode:'single',quickMultiPersonRows:[],quickMultiPersonReviewOpen:false};
  var violationLogState={loading:false,loaded:false,error:'',records:[],employees:[],query:'',mode:'all',status:'all',workflowStatus:'all',dateFrom:'',dateTo:'',employeeCode:'',page:1,pageSize:30,total:0,permission:{canView:false,canRecord:false,canEditTest:false,canCancel:false},history:{},historyLoading:{},taskStatus:{},taskStatusLoading:{},taskHistory:{},taskHistoryLoading:{},taskHistoryError:{},autoOpenedFocusKey:''};
  function invalidateViolationLog(){violationLogState.loaded=false;violationLogState.page=1;violationLogState.history={};}

  /* PHF Checklist Evidence 1.41.0: upload ảnh/PDF minh chứng thật lên Supabase
     Storage. Mỗi "scope" (item.id ở nhập nhanh, row.id ở nhiều ngày, 'detail' ở
     chi tiết, hoặc '__shared__' khi bật "Dùng cùng minh chứng") giữ danh sách
     file độc lập trong violationUiState.evidence. File chỉ thật sự thuộc về một
     bản ghi sau khi attachChecklistEvidence chạy xong ngay sau khi lưu lỗi. */
  var EVIDENCE_MAX_FILES=5;
  var EVIDENCE_MAX_BYTES=10*1024*1024;
  var EVIDENCE_ALLOWED_MIME=['image/jpeg','image/png','image/webp','application/pdf'];
  function evidenceScope(scopeKey){if(!violationUiState.evidence)violationUiState.evidence={};if(!violationUiState.evidence[scopeKey])violationUiState.evidence[scopeKey]={files:[]};return violationUiState.evidence[scopeKey];}
  function evidenceFormatSize(bytes){bytes=Number(bytes||0);if(bytes<1024)return bytes+' B';if(bytes<1024*1024)return (bytes/1024).toFixed(0)+' KB';return (bytes/1024/1024).toFixed(1)+' MB';}
  function evidenceDoneDraftIds(scopeKey){return evidenceScope(scopeKey).files.filter(function(f){return f.status==='done'&&f.evidenceDraftId;}).map(function(f){return f.evidenceDraftId;});}
  function evidenceHasPending(scopeKey){return evidenceScope(scopeKey).files.some(function(f){return f.status==='uploading';});}
  function evidenceAnyPending(){return Object.keys(violationUiState.evidence||{}).some(function(k){return evidenceHasPending(k);});}
  function evidenceClearScope(scopeKey){if(violationUiState.evidence)delete violationUiState.evidence[scopeKey];}
  function evidenceClearAll(){violationUiState.evidence={};}
  function evidenceNewLocalId(){return 'ev-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
  function evidenceItemHtml(scopeKey,f){
    var statusLabel=f.status==='uploading'?'Đang tải...':f.status==='error'?('Lỗi'+(f.error?': '+esc(f.error):'')):'Đã tải';
    var statusClass=f.status==='uploading'?'is-uploading':f.status==='error'?'is-error':'is-done';
    return '<li class="phfck-evidence-item '+statusClass+'" data-phfck-evidence-item="'+esc(f.localId)+'">'
      +'<span class="phfck-evidence-item-icon" aria-hidden="true">'+(f.mimeType==='application/pdf'?'📄':'🖼')+'</span>'
      +'<span class="phfck-evidence-item-meta"><b>'+esc(f.name)+'</b><small>'+evidenceFormatSize(f.size)+' · '+statusLabel+'</small></span>'
      +(f.status==='error'?'<button type="button" class="phfck-evidence-retry" data-phfck-evidence-retry="'+esc(scopeKey)+'|'+esc(f.localId)+'">Thử lại</button>':'')
      +'<button type="button" class="phfck-evidence-remove" data-phfck-evidence-remove="'+esc(scopeKey)+'|'+esc(f.localId)+'" aria-label="Xóa '+esc(f.name)+'" '+(f.status==='uploading'?'disabled':'')+'>×</button>'
    +'</li>';
  }
  function evidencePickerHtml(scopeKey){
    var scope=evidenceScope(scopeKey),files=scope.files,count=files.length,full=count>=EVIDENCE_MAX_FILES;
    return '<div class="phfck-evidence-picker" data-phfck-evidence-scope="'+esc(scopeKey)+'">'
      +'<div class="phfck-evidence-actions">'
        +'<label class="phfck-evidence-btn'+(full?' is-disabled':'')+'"><input type="file" accept="image/*" capture="environment" data-phfck-evidence-input="'+esc(scopeKey)+'" '+(full?'disabled':'')+' hidden><span>📷 Chụp ảnh</span></label>'
        +'<label class="phfck-evidence-btn'+(full?' is-disabled':'')+'"><input type="file" accept="'+EVIDENCE_ALLOWED_MIME.join(',')+'" multiple data-phfck-evidence-input="'+esc(scopeKey)+'" '+(full?'disabled':'')+' hidden><span>📁 Chọn file</span></label>'
        +'<span class="phfck-evidence-count">'+count+'/'+EVIDENCE_MAX_FILES+'</span>'
      +'</div>'
      +(files.length?'<ul class="phfck-evidence-list">'+files.map(function(f){return evidenceItemHtml(scopeKey,f);}).join('')+'</ul>':'<p class="phfck-evidence-empty">Chưa có ảnh/file minh chứng.</p>')
      +'<div class="phfck-evidence-error" data-phfck-evidence-error="'+esc(scopeKey)+'" hidden></div>'
    +'</div>';
  }
  function refreshEvidenceWidget(root,scopeKey){
    if(!root)return;
    var host=root.querySelector('[data-phfck-evidence-scope="'+cssEscape(scopeKey)+'"]');
    if(!host)return;
    host.outerHTML=evidencePickerHtml(scopeKey);
  }
  function evidenceShowError(root,scopeKey,message){
    var box=root&&root.querySelector('[data-phfck-evidence-error="'+cssEscape(scopeKey)+'"]');
    if(box){box.hidden=!message;box.textContent=message||'';}
  }
  function evidenceValidateFile(file){
    if(!file)return 'File không hợp lệ.';
    if(EVIDENCE_ALLOWED_MIME.indexOf(file.type)<0)return 'Chỉ chấp nhận ảnh JPG/PNG/WEBP hoặc PDF.';
    if(file.size<=0||file.size>EVIDENCE_MAX_BYTES)return 'Mỗi file phải nhỏ hơn 10MB.';
    return '';
  }
  async function evidenceUploadFile(root,scopeKey,employeeCode,file){
    var scope=evidenceScope(scopeKey);
    var entry={localId:evidenceNewLocalId(),name:file.name||'file',size:file.size||0,mimeType:file.type||'',status:'uploading',evidenceDraftId:'',error:'',file:file};
    scope.files.push(entry);
    refreshEvidenceWidget(root,scopeKey);
    try{
      var createRes=await fetch('/api/data?checklistEvidence=1',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action:'createChecklistEvidenceUpload',employeeCode:employeeCode,fileName:file.name,mimeType:file.type,sizeBytes:file.size})});
      var createData=await createRes.json().catch(function(){return {};});
      if(!createRes.ok||createData.ok===false)throw new Error(createData.message||createData.error||'Không tạo được đường dẫn tải lên.');
      var putRes=await fetch(createData.signedUrl,{method:'PUT',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});
      if(!putRes.ok)throw new Error('Tải file lên Storage thất bại (mạng chậm hoặc bị gián đoạn).');
      var finalizeRes=await fetch('/api/data?checklistEvidence=1',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action:'finalizeChecklistEvidenceUpload',employeeCode:employeeCode,evidenceId:createData.evidenceId,storagePath:createData.storagePath,fileName:file.name,mimeType:file.type})});
      var finalizeData=await finalizeRes.json().catch(function(){return {};});
      if(!finalizeRes.ok||finalizeData.ok===false)throw new Error(finalizeData.message||finalizeData.error||'Không xác nhận được file vừa tải lên.');
      entry.status='done';
      entry.evidenceDraftId=finalizeData.evidenceDraftId;
      entry.error='';
    }catch(err){
      entry.status='error';
      entry.error=err&&err.message?err.message:'Tải lên thất bại.';
    }
    refreshEvidenceWidget(root,scopeKey);
  }
  function evidenceHandleFileInput(root,inputEl){
    var scopeKey=inputEl.getAttribute('data-phfck-evidence-input')||'';
    var files=Array.prototype.slice.call(inputEl.files||[]);
    inputEl.value='';
    if(!scopeKey||!files.length)return;
    var person=violationSelectedEmployee();
    var employeeCode=person&&person.code||'';
    if(!employeeCode){evidenceShowError(root,scopeKey,'Vui lòng chọn nhân sự trước khi tải minh chứng.');return;}
    var scope=evidenceScope(scopeKey);
    var remaining=EVIDENCE_MAX_FILES-scope.files.length;
    if(remaining<=0){evidenceShowError(root,scopeKey,'Đã đạt tối đa '+EVIDENCE_MAX_FILES+' file cho một lỗi.');return;}
    var accepted=files.slice(0,remaining);
    if(files.length>remaining)evidenceShowError(root,scopeKey,'Chỉ nhận thêm '+remaining+' file (tối đa '+EVIDENCE_MAX_FILES+'/lỗi). Các file dư đã được bỏ qua.');
    else evidenceShowError(root,scopeKey,'');
    accepted.forEach(function(file){
      var err=evidenceValidateFile(file);
      if(err){
        evidenceScope(scopeKey).files.push({localId:evidenceNewLocalId(),name:file.name||'file',size:file.size||0,mimeType:file.type||'',status:'error',evidenceDraftId:'',error:err});
        refreshEvidenceWidget(root,scopeKey);
        return;
      }
      evidenceUploadFile(root,scopeKey,employeeCode,file);
    });
  }
  function evidenceRemoveFile(root,scopeKey,localId){
    var scope=evidenceScope(scopeKey);
    var entry=scope.files.find(function(f){return f.localId===localId;});
    if(!entry||entry.status==='uploading')return;
    scope.files=scope.files.filter(function(f){return f.localId!==localId;});
    refreshEvidenceWidget(root,scopeKey);
    if(entry.status==='done'&&entry.evidenceDraftId){
      fetch('/api/data?checklistEvidence=1',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action:'deleteChecklistEvidence',evidenceId:entry.evidenceDraftId})}).catch(function(){});
    }
  }
  function evidenceRetryFile(root,scopeKey,localId){
    var scope=evidenceScope(scopeKey);
    var entry=scope.files.find(function(f){return f.localId===localId;});
    if(!entry||!entry.file)return;
    var person=violationSelectedEmployee();
    var employeeCode=person&&person.code||'';
    scope.files=scope.files.filter(function(f){return f.localId!==localId;});
    if(!employeeCode){evidenceShowError(root,scopeKey,'Vui lòng chọn nhân sự trước khi tải minh chứng.');refreshEvidenceWidget(root,scopeKey);return;}
    evidenceUploadFile(root,scopeKey,employeeCode,entry.file);
  }
