  function checklistModalLayers(){var root=document.getElementById('phfChecklistRoot');if(!root)return[];var seen=[];return Array.prototype.slice.call(root.querySelectorAll('[data-phfck-modal-layer],[data-phfck-submodal]')).filter(function(layer){if(!layer||!layer.isConnected||seen.indexOf(layer)!==-1)return false;seen.push(layer);return true;});}
