  function waitChecklistOverviewRetry(ms){return new Promise(function(resolve){setTimeout(resolve,ms);});}
  async function waitChecklistOverviewAuth(){
    try{if(typeof window.phfWhenAuthReady==='function')await window.phfWhenAuthReady();}catch(_e){}
    try{if(typeof window.phfWaitForAuthTransition==='function')await window.phfWaitForAuthTransition();}catch(_e){}
    if(user())return true;
    for(var i=0;i<20;i++){await waitChecklistOverviewRetry(150);if(user())return true;}
    throw new Error('Phiên đăng nhập chưa sẵn sàng. Hệ thống sẽ tự tải lại dữ liệu.');
  }
  async function requestChecklistOverview(){
    await waitChecklistOverviewAuth();
    var lastError=null,delays=[400,900,1600,2600];
    for(var attempt=0;attempt<5;attempt++){
      try{
        var response=await fetch('/api/data?checklistOverview=1&t='+Date.now(),{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json','Cache-Control':'no-cache, no-store','Pragma':'no-cache'},body:JSON.stringify({action:'listChecklistTasks',scope:'all',status:'all'})});
        var data=await response.json().catch(function(){return {};});
        if(!response.ok||data.ok===false){var err=new Error(data.message||data.error||'Không thể tải dữ liệu Tổng quan.');err.status=response.status;throw err;}
        if(!data.summary||typeof data.summary!=='object')throw new Error('Dữ liệu Tổng quan trả về chưa đầy đủ.');
        return data;
      }catch(error){
        lastError=error;
        if(attempt<4){
          if(error&&Number(error.status)===401){try{if(typeof window.phfWhenAuthReady==='function')await window.phfWhenAuthReady();}catch(_e){}}
          await waitChecklistOverviewRetry(delays[attempt]);
        }
      }
    }
    throw lastError||new Error('Chưa thể kết nối dữ liệu Tổng quan.');
  }
  async function loadChecklistOverview(root,force){
    var fresh=overviewUiState.loaded&&Date.now()-Number(overviewUiState.loadedAt||0)<15000;
    if(!force&&fresh)return true;
    if(overviewUiState.request)return overviewUiState.request;
    overviewUiState.loading=true;overviewUiState.error='';
    syncChecklistOverviewLoadingOverlay(root);
    var requestId=++overviewUiState.requestId;
    renderChecklistOverviewIfCurrent(root);
    var request=(async function(){
      try{
        var data=await requestChecklistOverview();
        /* Lần mở đầu chờ một nhịp rồi xác nhận lại dữ liệu sau khi auth/session ổn định.
           Chỉ render kết quả cuối, tránh hiển thị tạm 0 rồi nhảy sang số thật. */
        if(!overviewUiState.loaded){await waitChecklistOverviewRetry(450);data=await requestChecklistOverview();}
        if(requestId!==overviewUiState.requestId)return false;
        overviewUiState.taskSummary=data.summary;
        overviewUiState.timingPolicy=data.timingPolicy||overviewUiState.timingPolicy;
        overviewUiState.loaded=true;
        overviewUiState.loadedAt=Date.now();
        overviewUiState.error='';
        return true;
      }catch(error){
        if(requestId!==overviewUiState.requestId)return false;
        /* Không xóa dữ liệu tốt gần nhất khi mạng/session chập chờn. */
        overviewUiState.error=error&&error.message||'Chưa thể kết nối dữ liệu việc.';
        return false;
      }finally{
        if(requestId===overviewUiState.requestId){overviewUiState.loading=false;overviewUiState.request=null;renderChecklistOverviewIfCurrent(root);syncChecklistOverviewLoadingOverlay(root);}
      }
    })();
    overviewUiState.request=request;
    return request;
  }
