  var assessmentProfileUiState={loading:false,loaded:false,error:'',errorCode:'',requestToken:0,ownerKey:'',selectedMonth:'',selectedYear:'',selectedTargetCode:'',targetQuery:'',pickerOpen:false,data:null};
