  function ensureChecklistXlsx(){
    if(window.XLSX)return Promise.resolve(window.XLSX);
    if(window.__phfXlsxLoadingPromise)return window.__phfXlsxLoadingPromise;
    window.__phfXlsxLoadingPromise=new Promise(function(resolve,reject){
      var settled=false;
      function done(){if(settled)return;settled=true;if(window.XLSX)resolve(window.XLSX);else reject(new Error('Không khởi tạo được thư viện Excel.'));}
      function failed(){if(settled)return;settled=true;reject(new Error('Không tải được thư viện Excel từ /assets/vendor/xlsx.full.min.js.'));}
      var existing=document.querySelector('script[data-phfck-xlsx-loader],script[src*="xlsx.full.min.js"]');
      if(existing){
        existing.addEventListener('load',done,{once:true});
        existing.addEventListener('error',failed,{once:true});
        setTimeout(function(){if(window.XLSX)done();},0);
        return;
      }
      var script=document.createElement('script');
      script.src='/assets/vendor/xlsx.full.min.js?v=0.18.5_phf_1.35.7';
      script.async=true;
      script.setAttribute('data-phfck-xlsx-loader','1');
      script.onload=done;
      script.onerror=failed;
      document.head.appendChild(script);
    }).catch(function(error){
      window.__phfXlsxLoadingPromise=null;
      throw error;
    });
    return window.__phfXlsxLoadingPromise;
  }
