        savedRows.forEach(function(row){var key=normalizeText(row.employeeKey||row.employeeCode||row.employeeId).toLowerCase();if(!key)return;map[key]=row;checklistAssignmentDbState.versions[key]=row.updatedAt||'';var local=rows.find(function(x){return x.employeeKey===key;});checklistAssignmentDbState.baseline[key]=assignmentComparable(local||row);});
        target.checklistAssignments=Object.keys(map).map(function(key){return map[key];});target.checklistAssignmentsReady=true;target.checklistAssignmentsError='';return data;
