      +'<tr class="phfck-total-final"><td></td><td><b>Tổng kết quả</b></td><td></td><td><strong>100%</strong></td><td></td><td></td><td></td><td><strong>91,5 điểm</strong></td><td><span class="phfck-result-chip is-pass">Đạt</span></td></tr>'
