  function violationLocationOptions(){
    var person=violationSelectedEmployee(),values=[];
    if(person){
      var department=normalizeText(person.department),ownBranch=normalizeText(person.branch);
      violationEligibleEmployees().forEach(function(item){
        var branch=normalizeText(item.branch);
        if(branch&&normalizeText(item.department)===department&&values.indexOf(branch)<0)values.push(branch);
      });
      if(ownBranch&&values.indexOf(ownBranch)<0)values.unshift(ownBranch);
      values.sort(function(a,b){return a.localeCompare(b,'vi');});
    }
    var current=normalizeText(violationUiState.location||(person&&person.branch)||'');
    if(current&&values.indexOf(current)<0)current=normalizeText(person&&person.branch);
    return '<option value="">'+(person?'Chọn địa điểm trong phạm vi '+esc(person.department||'nhân sự'):'Chọn nhân sự trước')+'</option>'+values.map(function(v){return '<option value="'+esc(v)+'" '+(current===v?'selected':'')+'>'+esc(v)+'</option>';}).join('');
  }
  function violationTemplateOptions(){
    var ctx=violationAssignmentContext();
    if(!ctx.ok)return '<option value="">Tự động theo phân công</option>';
    return '<option value="'+esc(ctx.templateId)+'" selected>'+esc(ctx.meta.name)+' · '+esc(ctx.version)+'</option>';
  }
  function violationCriteriaFromDefinition(definition){
    var result=[];(definition&&Array.isArray(definition.groups)?definition.groups:[]).forEach(function(group){
      (group.children||[]).forEach(function(child){
        (child.items||[]).forEach(function(item){
          var code=normalizeText(item&&item[0])||('TC-'+String(result.length+1).padStart(2,'0'));
          var text=normalizeText(item&&item[1]);if(!text)return;
          var factor=Math.max(1,Number(item&&item[2])||1);
          result.push({id:code,code:code,group:normalizeText(child.name||group.name)||'Tiêu chuẩn công việc',text:text,points:factor,evidence:'recommended'});
        });
      });
    });return result;
  }
  function violationCriteriaForContext(ctx){
    if(!ctx||!ctx.ok)return [];
    var versions=checklistTemplateVersions(ctx.templateId),chosen=versions.find(function(v){return normalizeText(v.version)===normalizeText(ctx.version);})||null;
    var definition=chosen&&chosen.definition&&typeof chosen.definition==='object'?chosen.definition:null;
    if(!definition){var row=checklistTemplateDatabaseRow(ctx.templateId);definition=row&&row.definition&&typeof row.definition==='object'?row.definition:null;}
    if(!definition){var override=loadBulkOverride(ctx.templateId);definition=override?{groups:override.groups||[]}:null;}
    return violationCriteriaFromDefinition(definition);
  }
  function violationLiveCriteria(){return violationCriteriaForContext(violationAssignmentContext());}
