  function violationEvaluationPeriodValue(){
    var period=roleWorkspaceState&&roleWorkspaceState.monthlyPeriod||null;
    var raw=normalizeText(period&&(period.period_month||period.month||period.code||period.value)||'');
    if(!raw&&roleWorkspaceState&&roleWorkspaceState.monthlyForm)raw=normalizeText(roleWorkspaceState.monthlyForm.period_month||'');
    if(!raw)raw=normalizeText(violationUiState.date||todayIso()).slice(0,7);
    var match=raw.match(/^(\d{4})-(\d{2})/);
    if(match)return match[2]+'/'+match[1];
    var vi=raw.match(/^(\d{2})[\/.-](\d{4})/);
    if(vi)return vi[1]+'/'+vi[2];
    return raw||'Chưa xác định';
  }
