    if(mode==='log')violationLogFilteredRows().forEach(function(r){rows.push([r.employee_code||'',r.employee_name||'',r.occurred_date||'',String(r.occurred_time||'').slice(0,5),r.location||'',r.criterion_code||'',r.criterion_name||'',r.note||'',r.points||0,'','','',r.is_test===true?'TEST':(r.record_status==='cancelled'?'Đã hủy':'Chính thức')]);});
