      +'<button type="button" class="'+(mode==='multi'?'active':'')+'" data-phfck-quick-person-mode="multi" role="tab" aria-selected="'+(mode==='multi'?'true':'false')+'">Nhiều nhân viên</button>'
    +'</div>';
