      +'<label class="phfck-permission-reason"><span>Lý do cấp/thay đổi quyền *</span><textarea rows="3" placeholder="Ví dụ: Phân quyền Trợ lý Giám đốc theo cơ cấu áp dụng từ tháng 08/2026" data-phfck-permission-field="reason">'+esc(grant.reason||'')+'</textarea></label>'
      +'</div><div class="phfck-modal-foot">'+(editing&&grant.isActive?'<button type="button" class="phfck-danger-soft" data-phfck-permission-disable="'+esc(grant.id)+'">Ngừng quyền</button>':'')+'<button type="button" class="phfck-secondary" data-phfck-close-submodal>Hủy</button><button type="button" class="phfck-primary" data-phfck-permission-save="'+esc(grant.id||'')+'">Lưu quyền</button></div></div></div>';
