  function defaultRepeatPolicyUi(){return {effectiveFromPeriod:'2026-08',monthlyWarningCount:2,trainingOccurrenceCount:3,trainingWindowMonths:3,reason:'',updatedAt:'',updatedBy:'',source:'default',classIntegration:false};}
  function normalizeRepeatPolicyUi(policy){var base=defaultRepeatPolicyUi(),source=policy||{};return {id:source.id||'',effectiveFromPeriod:/^\d{4}-(0[1-9]|1[0-2])$/.test(String(source.effectiveFromPeriod||''))?String(source.effectiveFromPeriod):base.effectiveFromPeriod,monthlyWarningCount:Math.max(2,Math.min(20,Math.round(Number(source.monthlyWarningCount)||base.monthlyWarningCount))),trainingOccurrenceCount:Math.max(2,Math.min(50,Math.round(Number(source.trainingOccurrenceCount)||base.trainingOccurrenceCount))),trainingWindowMonths:Math.max(1,Math.min(12,Math.round(Number(source.trainingWindowMonths)||base.trainingWindowMonths))),reason:source.reason||'',updatedAt:source.updatedAt||'',updatedBy:source.updatedBy||'',source:source.source||'default',classIntegration:false};}
  function repeatPolicyDraftValue(){if(!settingsUiState.repeatPolicyDraft)settingsUiState.repeatPolicyDraft=normalizeRepeatPolicyUi(settingsUiState.repeatPolicy||defaultRepeatPolicyUi());return settingsUiState.repeatPolicyDraft;}
  async function loadRepeatViolationPolicy(root,force){if(settingsUiState.repeatPolicyLoading||(!force&&settingsUiState.repeatPolicy))return;settingsUiState.repeatPolicyLoading=true;try{var response=await fetch('/api/data',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'getChecklistRepeatViolationPolicy'})}),data=await response.json().catch(function(){return {};});if(!response.ok||data.ok===false)throw new Error(data.message||'Không thể tải ngưỡng lỗi lặp lại.');settingsUiState.repeatPolicy=normalizeRepeatPolicyUi(data.policy||defaultRepeatPolicyUi());settingsUiState.repeatPolicies=Array.isArray(data.policies)?data.policies.map(normalizeRepeatPolicyUi):[settingsUiState.repeatPolicy];settingsUiState.repeatPolicyHistory=Array.isArray(data.history)?data.history:[];settingsUiState.repeatPolicyDraft=null;}catch(err){checklistToast('error','Chưa tải được ngưỡng lỗi lặp lại',err.message||'Vui lòng thử lại.',true);}finally{settingsUiState.repeatPolicyLoading=false;var workspace=root&&root.querySelector('[data-phfck-workspace]');if(workspace&&adminViewFromPath(location.pathname)==='settings'&&settingsUiState.section==='violationRules')workspace.innerHTML=settingsHtml();}}
  function repeatPolicyFromDom(root){return {monthlyWarningCount:Number((root.querySelector('[data-phfck-repeat-policy-field="monthly"]')||{}).value),trainingOccurrenceCount:Number((root.querySelector('[data-phfck-repeat-policy-field="training"]')||{}).value),trainingWindowMonths:Number((root.querySelector('[data-phfck-repeat-policy-field="window"]')||{}).value),effectiveFromPeriod:(root.querySelector('[data-phfck-repeat-policy-field="period"]')||{}).value||'',reason:(root.querySelector('[data-phfck-repeat-policy-field="reason"]')||{}).value||''};}
  function repeatPolicyValidateUi(draft){var errors=[];if(!Number.isInteger(draft.monthlyWarningCount)||draft.monthlyWarningCount<2||draft.monthlyWarningCount>20)errors.push('Ngưỡng cảnh báo trong tháng phải từ 2 đến 20 lần.');if(!Number.isInteger(draft.trainingOccurrenceCount)||draft.trainingOccurrenceCount<2||draft.trainingOccurrenceCount>50)errors.push('Ngưỡng gợi ý đào tạo phải từ 2 đến 50 lần.');if(!Number.isInteger(draft.trainingWindowMonths)||draft.trainingWindowMonths<1||draft.trainingWindowMonths>12)errors.push('Khoảng theo dõi phải từ 1 đến 12 tháng.');if(draft.trainingOccurrenceCount<draft.monthlyWarningCount)errors.push('Ngưỡng gợi ý đào tạo không được thấp hơn ngưỡng cảnh báo trong tháng.');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(String(draft.effectiveFromPeriod||'')))errors.push('Kỳ bắt đầu áp dụng chưa hợp lệ.');if(String(draft.reason||'').trim().length<10)errors.push('Lý do thay đổi cần tối thiểu 10 ký tự.');return errors;}
  async function saveRepeatViolationPolicyUi(root){if(settingsUiState.repeatPolicySaving)return;var draft=repeatPolicyFromDom(root),errors=repeatPolicyValidateUi(draft);if(errors.length){checklistToast('warning','Chưa thể lưu ngưỡng lỗi lặp lại',errors.join(' '),true);return;}settingsUiState.repeatPolicySaving=true;try{var response=await fetch('/api/data',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'saveChecklistRepeatViolationPolicy',effectiveFromPeriod:draft.effectiveFromPeriod,monthlyWarningCount:draft.monthlyWarningCount,trainingOccurrenceCount:draft.trainingOccurrenceCount,trainingWindowMonths:draft.trainingWindowMonths,reason:draft.reason})}),data=await response.json().catch(function(){return {};});if(!response.ok||data.ok===false)throw new Error(data.message||'Không thể lưu ngưỡng lỗi lặp lại.');settingsUiState.repeatPolicy=normalizeRepeatPolicyUi(data.policy);settingsUiState.repeatPolicyEditing=false;settingsUiState.repeatPolicyDraft=null;settingsUiState.repeatSuggestions=null;settingsUiState.repeatPolicySaving=false;await loadRepeatViolationPolicy(root,true);checklistToast('success','Đã lưu ngưỡng lỗi lặp lại','Chỉ tạo cảnh báo và gợi ý trong PHF Checklist; không tự liên kết PHF Class.',true);}catch(err){checklistToast('error','Không thể lưu ngưỡng lỗi lặp lại',err.message||'Vui lòng thử lại.',true);}finally{settingsUiState.repeatPolicySaving=false;}}
  async function loadRepeatViolationSuggestions(root){if(settingsUiState.repeatSuggestionLoading)return;var period=(root.querySelector('[data-phfck-repeat-suggestion-period]')||{}).value||settingsUiState.repeatSuggestionPeriod||todayIso().slice(0,7);settingsUiState.repeatSuggestionPeriod=period;settingsUiState.repeatSuggestionLoading=true;var workspace=root.querySelector('[data-phfck-workspace]');if(workspace)workspace.innerHTML=settingsHtml();try{var response=await fetch('/api/data',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'getChecklistRepeatViolationSuggestions',period:period})}),data=await response.json().catch(function(){return {};});if(!response.ok||data.ok===false)throw new Error(data.message||'Không thể tải danh sách gợi ý.');settingsUiState.repeatSuggestions=data;}catch(err){settingsUiState.repeatSuggestions=null;checklistToast('error','Chưa tải được danh sách gợi ý',err.message||'Vui lòng thử lại.',true);}finally{settingsUiState.repeatSuggestionLoading=false;var doneWorkspace=root.querySelector('[data-phfck-workspace]');if(doneWorkspace)doneWorkspace.innerHTML=settingsHtml();}}
  function repeatPolicyHistoryHtml(){var rows=(settingsUiState.repeatPolicyHistory||[]).slice(0,5);if(!rows.length)return '<div class="phfck-settings-empty">Chưa có lịch sử thay đổi.</div>';return '<div class="phfck-late-policy-history">'+rows.map(function(row){return '<div><span>'+esc((row.changed_at||'').slice(0,16).replace('T',' '))+'</span><p><b>'+esc(row.changed_by_name||'Admin')+'</b><small>Kỳ '+esc(row.effective_from_period||'—')+' · '+esc(row.reason||'Không có lý do')+'</small></p></div>';}).join('')+'</div>';}
  function repeatSuggestionsHtml(){var data=settingsUiState.repeatSuggestions;if(settingsUiState.repeatSuggestionLoading)return '<div class="phfck-settings-empty">Đang tổng hợp gợi ý theo kỳ…</div>';if(!data)return '<div class="phfck-settings-empty">Chọn kỳ để xem các trường hợp cần lưu ý theo ngưỡng đang áp dụng.</div>';var rows=Array.isArray(data.suggestions)?data.suggestions:[];if(!rows.length)return '<div class="phfck-settings-empty">'+(data.notEffectiveYet?esc(data.message||'Chính sách chưa có hiệu lực ở kỳ được chọn.'):('Kỳ '+esc(data.period||settingsUiState.repeatSuggestionPeriod)+' chưa có trường hợp đạt ngưỡng cảnh báo hoặc gợi ý đào tạo.'))+'</div>';return '<div class="phfck-repeat-summary"><div><strong>'+Number(data.warningCount||0)+'</strong><span>Cảnh báo trong tháng</span></div><div><strong>'+Number(data.trainingSuggestionCount||0)+'</strong><span>Gợi ý đào tạo</span></div><div><strong>'+Number(rows.length)+'</strong><span>Nhân viên + tiêu chí</span></div></div><div class="phfck-repeat-suggestion-list">'+rows.slice(0,12).map(function(row){return '<div class="'+(row.trainingSuggested?'is-training':'is-warning')+'"><span>'+(row.trainingSuggested?'Gợi ý':'Cảnh báo')+'</span><p><b>'+esc(row.employeeName||row.employeeCode)+'</b><small>'+esc(row.employeeCode)+' · '+esc(row.criterionName||row.criterionCode)+'</small></p><strong>'+Number(row.monthlyCount||0)+' lần kỳ này<small>'+Number(row.windowCount||0)+' lần / '+Number(data.policy&&data.policy.trainingWindowMonths||3)+' tháng</small></strong></div>';}).join('')+'</div><div class="phfck-repeat-no-class"><b>Chỉ gợi ý để Admin xem xét</b><span>Không gọi API, không tạo lớp học và không tự đăng ký PHF Class.</span></div>';}
  function repeatViolationPolicySettingsHtml(){var policy=normalizeRepeatPolicyUi(settingsUiState.repeatPolicy||defaultRepeatPolicyUi()),editing=settingsUiState.repeatPolicyEditing,draft=editing?repeatPolicyDraftValue():policy,busy=settingsUiState.repeatPolicyLoading||settingsUiState.repeatPolicySaving;return '<article class="phfck-panel phfck-settings-card phfck-settings-wide phfck-repeat-policy-card"><div class="phfck-panel-head"><div><small>NGƯỠNG LỖI LẶP LẠI</small><h3>Cảnh báo và gợi ý theo kỳ</h3></div><div class="phfck-late-policy-head-actions phfck-policy-head-actions"><span class="phfck-status phfck-policy-period-chip">'+(settingsUiState.repeatPolicyLoading?'Đang tải':'Áp dụng từ '+esc(policy.effectiveFromPeriod))+'</span>'+(!editing?'<button type="button" class="phfck-secondary phfck-settings-edit-btn" data-phfck-repeat-policy-edit '+(busy?'disabled':'')+'>Sửa ngưỡng</button>':'')+'</div></div><div class="phfck-repeat-policy-note"><b>Không tự trừ thêm điểm.</b><span>Chỉ tính cùng nhân viên + cùng tiêu chí trên lỗi chính thức; không tính dữ liệu TEST hoặc lỗi đã hủy.</span></div>'+(editing?'<div class="phfck-repeat-policy-edit-grid"><label><small>Cảnh báo trong cùng tháng</small><div><input type="number" min="2" max="20" step="1" value="'+esc(draft.monthlyWarningCount)+'" data-phfck-repeat-policy-field="monthly"><span>lần</span></div></label><label><small>Gợi ý đào tạo khi đạt</small><div><input type="number" min="2" max="50" step="1" value="'+esc(draft.trainingOccurrenceCount)+'" data-phfck-repeat-policy-field="training"><span>lần</span></div></label><label><small>Trong khoảng theo dõi</small><div><input type="number" min="1" max="12" step="1" value="'+esc(draft.trainingWindowMonths)+'" data-phfck-repeat-policy-field="window"><span>tháng</span></div></label></div><div class="phfck-policy-config-row phfck-late-policy-config"><label><b>Áp dụng từ kỳ</b><input type="month" value="'+esc(draft.effectiveFromPeriod)+'" data-phfck-repeat-policy-field="period"><small>Kỳ đã khóa không được sửa chính sách.</small></label><label class="is-reason"><b>Lý do thay đổi</b><input type="text" maxlength="500" value="'+esc(draft.reason||'')+'" placeholder="Tối thiểu 10 ký tự" data-phfck-repeat-policy-field="reason"><small>Lưu người thay đổi, thời gian và giá trị trước–sau.</small></label></div><div class="phfck-policy-footer"><p>Không tự động đăng ký khóa học; Admin chỉ nhận danh sách gợi ý để xem xét.</p><div><button type="button" class="phfck-secondary" data-phfck-repeat-policy-cancel>Hủy</button><button type="button" class="phfck-primary" data-phfck-repeat-policy-save '+(busy?'disabled':'')+'>'+(settingsUiState.repeatPolicySaving?'Đang lưu…':'Lưu ngưỡng')+'</button></div></div>':'<div class="phfck-repeat-grid phfck-repeat-grid-live"><div><strong>'+String(policy.monthlyWarningCount).padStart(2,'0')+'</strong><b>lần trong cùng tháng</b><p>Cảnh báo quản lý theo dõi.</p></div><div><strong>'+String(policy.trainingOccurrenceCount).padStart(2,'0')+'</strong><b>lần trong '+policy.trainingWindowMonths+' tháng</b><p>Gợi ý Admin xem xét đào tạo.</p></div><div><strong>✓</strong><b>Chỉ gợi ý</b><p>Không tự liên kết PHF Class.</p></div></div><div class="phfck-late-policy-meta"><span>Cập nhật gần nhất</span><b>'+esc(policyActorLabel(policy.updatedBy))+'</b><small>'+esc(policy.updatedAt?policy.updatedAt.slice(0,16).replace('T',' '):'Chưa có thay đổi')+'</small></div>')+'</article><article class="phfck-panel phfck-settings-card phfck-settings-wide phfck-repeat-preview-card phfck-settings-preview-card"><div class="phfck-panel-head"><div><small>DANH SÁCH GỢI Ý</small><h3>Xem trước theo kỳ</h3></div><span class="phfck-status phfck-readonly-chip">Chỉ đọc</span></div><div class="phfck-repeat-preview-tools"><label><b>Kỳ cần xem</b><input type="month" value="'+esc(settingsUiState.repeatSuggestionPeriod||todayIso().slice(0,7))+'" data-phfck-repeat-suggestion-period></label><button type="button" class="phfck-secondary phfck-settings-inline-btn" data-phfck-repeat-suggestion-load '+(settingsUiState.repeatSuggestionLoading?'disabled':'')+'>'+(settingsUiState.repeatSuggestionLoading?'Đang tổng hợp…':'Xem gợi ý')+'</button></div>'+repeatSuggestionsHtml()+'</article><article class="phfck-panel phfck-settings-card phfck-settings-wide phfck-settings-history-card"><div class="phfck-panel-head"><div><small>LỊCH SỬ NGƯỠNG</small><h3>Thay đổi gần đây</h3></div><span class="phfck-status phfck-readonly-chip">Chỉ đọc</span></div>'+repeatPolicyHistoryHtml()+'</article>';}
  function settingSwitch(label,desc,checked,locked){return '<div class="phfck-setting-row"><div><b>'+esc(label)+'</b><p>'+esc(desc)+'</p></div><label class="phfck-switch '+(locked?'is-locked':'')+'"><input type="checkbox" '+(checked?'checked':'')+' '+(locked?'disabled':'')+'><span></span></label></div>';}
  function policyActorLabel(value){var text=String(value||'').trim();if(!text)return 'Hệ thống PHF Checklist';if(/^PHF Checklist(?:\s+\d+(?:\.\d+)*)?/i.test(text))return 'Hệ thống PHF Checklist';return text;}
  function fixedSystemRule(label,desc){return '<div class="phfck-fixed-system-rule"><span aria-hidden="true">✓</span><div><b>'+esc(label)+'</b><p>'+esc(desc)+'</p></div><strong>Đang áp dụng</strong></div>';}
