  async function loadMonthlyScorePolicy(root,force){if(settingsUiState.scorePolicyLoading||(!force&&settingsUiState.scorePolicy))return;settingsUiState.scorePolicyLoading=true;try{var response=await fetch('/api/data',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'getChecklistMonthlyScorePolicy'})}),data=await response.json().catch(function(){return {};});if(!response.ok||data.ok===false)throw new Error(data.message||'Không thể tải trọng số phiếu tháng.');settingsUiState.scorePolicy=normalizeMonthlyScorePolicyUi(data.policy||defaultMonthlyScorePolicyUi());settingsUiState.scorePolicies=Array.isArray(data.policies)?data.policies.map(normalizeMonthlyScorePolicyUi):[settingsUiState.scorePolicy];settingsUiState.scorePolicyHistory=Array.isArray(data.history)?data.history:[];settingsUiState.scorePolicyDraft=null;}catch(err){checklistToast('error','Chưa tải được trọng số phiếu tháng',err.message||'Vui lòng thử lại.',true);}finally{settingsUiState.scorePolicyLoading=false;var workspace=root&&root.querySelector('[data-phfck-workspace]');if(workspace&&adminViewFromPath(location.pathname)==='settings'&&settingsUiState.section==='violationRules')workspace.innerHTML=settingsHtml();}}
