  function monthlyScorePolicyHistoryHtml(){var rows=settingsUiState.scorePolicyHistory||[];if(!rows.length)return '<div class="phfck-permission-empty"><b>Chưa có lịch sử thay đổi</b><p>Lịch sử sẽ xuất hiện sau lần Admin lưu đầu tiên.</p></div>';return '<div class="phfck-late-policy-history">'+rows.slice(0,10).map(function(row){var before=normalizeMonthlyScorePolicyUi(row.beforeData||{}),after=normalizeMonthlyScorePolicyUi(row.afterData||{});return '<div><span>'+esc(row.changedAt?String(row.changedAt).slice(0,16).replace('T',' '):(row.effectiveFromPeriod||after.effectiveFromPeriod))+'</span><p><b>'+esc(before.selfWeight+':'+before.reviewWeight)+' → '+esc(after.selfWeight+':'+after.reviewWeight)+'</b><small>Kỳ '+esc(row.effectiveFromPeriod||after.effectiveFromPeriod)+' · '+esc(row.changedByName||'Admin')+' · '+esc(row.reason||'Không có lý do')+'</small></p></div>';}).join('')+'</div>';}
