  function scoringSettingsHtml(){return '<section class="phfck-settings-grid phfck-scoring-settings">'+monthlyScorePolicySettingsHtml()+'<article class="phfck-panel phfck-settings-card"><div class="phfck-panel-head"><div><small>ĐIỂM TUÂN THỦ</small><h3>Công thức nền</h3></div></div><div class="phfck-score-box"><span>Điểm đầu tháng</span><strong>100</strong><small>Trừ theo hệ số từng tiêu chí; điểm thấp nhất là 0.</small></div>'+fixedSystemRule('Không tự tăng hệ số khi lặp lại','Lỗi lặp lại chỉ tạo cảnh báo và gợi ý, không tự trừ thêm điểm.')+fixedSystemRule('Hủy lỗi hoàn điểm','Khi Admin hủy, hệ thống tính lại điểm kỳ liên quan.')+'</article><article class="phfck-panel phfck-settings-card"><div class="phfck-panel-head"><div><small>ĐÀO TẠO</small><h3>Giới hạn tích hợp</h3></div></div><div class="phfck-settings-callout"><b>Chỉ gợi ý trong Checklist</b><p>Không gọi API, không tạo lớp học và không tự đăng ký dữ liệu sang PHF Class.</p></div></article>'+repeatViolationPolicySettingsHtml()+'</section>';}

