  function monthlyCycleSettingsHtml(){var c=monthlyCycleValue(),busy=settingsUiState.monthlyCycleLoading||settingsUiState.monthlyCycleSaving||settingsUiState.monthlyCycleSyncing,w=c.window||{};return '<section class="phfck-settings-grid phfck-cycle-settings"><article class="phfck-panel phfck-settings-card phfck-settings-wide"><div class="phfck-panel-head"><div><small>CHU KỲ ĐÁNH GIÁ TỰ ĐỘNG</small><h3>Tạo kỳ tự động; tự đánh giá, thẩm định và khóa vào tháng kế tiếp</h3></div><span class="phfck-status is-live">'+(c.autoCreateEnabled?'Đang bật tự động':'Đang tắt')+'</span></div><div class="phfck-cycle-switch"><label><input type="checkbox" data-phfck-cycle-auto '+(c.autoCreateEnabled?'checked':'')+'><span><b>Tự động tạo và đồng bộ kỳ mới</b><small>Nếu kỳ đã tồn tại, hệ thống chỉ bổ sung phiếu còn thiếu.</small></span></label></div><div class="phfck-cycle-grid"><label><small>Khởi tạo kỳ từ</small><select data-phfck-cycle-source><option value="previous_period" '+(c.sourceMode!=='current_assignments'?'selected':'')+'>Kỳ liền trước + đối chiếu hiện hành</option><option value="current_assignments" '+(c.sourceMode==='current_assignments'?'selected':'')+'>Phân công hiện hành</option></select></label><label><small>Có hiệu lực từ kỳ</small><input type="month" value="'+esc(c.effectiveFromPeriod)+'" data-phfck-cycle-period></label><label><small>Ngày tạo kỳ</small><input type="number" min="1" max="28" value="'+esc(c.createDay)+'" data-phfck-cycle-create-day></label><label><small>Giờ chạy tự động</small><input type="time" value="'+esc(c.createTime)+'" data-phfck-cycle-create-time></label></div><div class="phfck-cycle-window-grid"><article><b>Tự đánh giá ở tháng kế tiếp</b><label>Từ ngày <input type="number" min="1" max="28" value="'+esc(c.selfStartDay)+'" data-phfck-cycle-self-start></label><label>Đến ngày <input type="number" min="1" max="28" value="'+esc(c.selfEndDay)+'" data-phfck-cycle-self-end></label></article><article><b>Thẩm định ở tháng kế tiếp</b><label>Từ ngày <input type="number" min="1" max="28" value="'+esc(c.reviewStartDay)+'" data-phfck-cycle-review-start></label><label>Đến ngày <input type="number" min="1" max="28" value="'+esc(c.reviewEndDay)+'" data-phfck-cycle-review-end></label><small>Phiếu vẫn hiển thị và cập nhật điểm Checklist trong suốt tháng đánh giá. Cửa sổ thẩm định mở ở tháng kế tiếp; nút thao tác chỉ bật khi nhân viên đã gửi tự đánh giá.</small></article><article><b>Khóa kỳ ở tháng kế tiếp</b><label>Ngày <input type="number" min="1" max="28" value="'+esc(c.lockDay)+'" data-phfck-cycle-lock-day></label><label>Giờ <input type="time" value="'+esc(c.lockTime)+'" data-phfck-cycle-lock-time></label></article></div><div class="phfck-cycle-example"><b>Cách áp dụng</b><span>Kỳ 08/2026 ghi nhận dữ liệu trong tháng 08; nếu cấu hình ngày 01–04 thì tự đánh giá, thẩm định và khóa diễn ra trong tháng 09/2026. Mỗi kỳ được chụp lịch riêng khi đồng bộ.</span></div><div class="phfck-policy-config-row"><label class="is-reason"><b>Lý do thay đổi</b><input type="text" maxlength="500" placeholder="Tối thiểu 10 ký tự" data-phfck-cycle-reason><small>Mọi thay đổi được lưu lịch sử; kỳ đã tạo giữ lịch snapshot riêng.</small></label></div><div class="phfck-policy-footer"><p>'+(w.reviewOpenAt?'Cửa sổ thẩm định kỳ '+esc(c.period||c.effectiveFromPeriod)+': '+esc(String(w.reviewOpenAt).replace('T',' ').slice(0,16))+' → '+esc(String(w.reviewDueAt).replace('T',' ').slice(0,16)):'Lịch cụ thể sẽ được chụp khi đồng bộ kỳ.')+'</p><div><button type="button" class="phfck-secondary" data-phfck-cycle-sync '+(busy?'disabled':'')+'>'+(settingsUiState.monthlyCycleSyncing?'Đang đồng bộ…':'Đồng bộ kỳ hiện tại')+'</button><button type="button" class="phfck-primary" data-phfck-cycle-save '+(busy?'disabled':'')+'>'+(settingsUiState.monthlyCycleSaving?'Đang lưu…':'Lưu chu kỳ')+'</button></div></div></article><article class="phfck-panel phfck-settings-card phfck-settings-wide phfck-cycle-override-card"><div class="phfck-panel-head"><div><small>NGOẠI LỆ THEO KỲ</small><h3>Điều chỉnh riêng một kỳ</h3></div><span class="phfck-status">Không ảnh hưởng kỳ sau</span></div><div class="phfck-cycle-grid"><label><small>Kỳ ngoại lệ</small><input type="month" value="'+esc(c.period||c.effectiveFromPeriod)+'" data-phfck-cycle-override-period></label><label><small>Tự đánh giá từ ngày</small><input type="number" min="1" max="28" value="'+esc(c.override&&c.override.self_start_day||c.selfStartDay)+'" data-phfck-cycle-override-self-start></label><label><small>Đến ngày</small><input type="number" min="1" max="28" value="'+esc(c.override&&c.override.self_end_day||c.selfEndDay)+'" data-phfck-cycle-override-self-end></label><label><small>Thẩm định từ ngày</small><input type="number" min="1" max="28" value="'+esc(c.override&&c.override.review_start_day||c.reviewStartDay)+'" data-phfck-cycle-override-review-start></label><label><small>Đến ngày</small><input type="number" min="1" max="28" value="'+esc(c.override&&c.override.review_end_day||c.reviewEndDay)+'" data-phfck-cycle-override-review-end></label><label><small>Khóa ngày</small><input type="number" min="1" max="28" value="'+esc(c.override&&c.override.lock_day||c.lockDay)+'" data-phfck-cycle-override-lock-day></label><label><small>Giờ khóa</small><input type="time" value="'+esc(c.override&&c.override.lock_time||c.lockTime)+'" data-phfck-cycle-override-lock-time></label></div><div class="phfck-policy-config-row"><label class="is-reason"><b>Lý do ngoại lệ</b><input type="text" maxlength="500" placeholder="Ví dụ: kéo dài kỳ do nghỉ lễ…" data-phfck-cycle-override-reason><small>Kỳ không có ngoại lệ tự dùng lịch mặc định ở trên.</small></label></div><div class="phfck-policy-footer"><p>'+(c.override?'Kỳ này đang dùng ngoại lệ đã lưu.':'Kỳ này đang dùng lịch mặc định.')+'</p><button type="button" class="phfck-secondary" data-phfck-cycle-override-save '+(busy?'disabled':'')+'>Lưu ngoại lệ kỳ</button></div></article></section>';}
  async function loadMonthlyOverduePolicy(root,force){if(settingsUiState.monthlyPolicyLoading||(!force&&settingsUiState.monthlyPolicy))return;settingsUiState.monthlyPolicyLoading=true;try{var r=await fetch('/api/data',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'getChecklistMonthlyOverduePolicy'})}),d=await r.json().catch(function(){return {};});if(!r.ok||d.ok===false)throw new Error(d.message||'Không thể tải chính sách quá hạn.');settingsUiState.monthlyPolicy=d.policy||null;if(d.policy){taskUiState.timingPolicy=d.policy;overviewUiState.timingPolicy=d.policy;}}catch(err){checklistToast('error','Chưa tải được chính sách',err.message||'Vui lòng kiểm tra API.',true);}finally{settingsUiState.monthlyPolicyLoading=false;var w=root&&root.querySelector('[data-phfck-workspace]');if(w&&settingsUiState.section==='cycle')w.innerHTML=settingsHtml();}}
  async function saveMonthlyOverduePolicyUi(root){if(settingsUiState.monthlyPolicySaving)return;var mode=(root.querySelector('[name=phfck-monthly-overdue-mode]:checked')||{}).value||'max',period=(root.querySelector('[data-phfck-monthly-policy-period]')||{}).value||'2026-08',reason=(root.querySelector('[data-phfck-monthly-policy-reason]')||{}).value||'';if(reason.trim().length<10){checklistToast('warning','Chưa thể lưu','Lý do thay đổi cần tối thiểu 10 ký tự.');return;}settingsUiState.monthlyPolicySaving=true;try{var r=await fetch('/api/data',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'saveChecklistMonthlyOverduePolicy',mode:mode,effectiveFromPeriod:period,reason:reason})}),d=await r.json().catch(function(){return {};});if(!r.ok||d.ok===false)throw new Error(d.message||'Không thể lưu chính sách.');settingsUiState.monthlyPolicy=d.policy;taskUiState.timingPolicy=d.policy;overviewUiState.timingPolicy=d.policy;var w=root.querySelector('[data-phfck-workspace]');if(w)w.innerHTML=settingsHtml();checklistToast('success','Đã lưu chính sách','Áp dụng từ kỳ '+period+'; các kỳ đã khóa không bị thay đổi.');}catch(err){checklistToast('error','Không thể lưu chính sách',err.message||'Vui lòng thử lại.',true);}finally{settingsUiState.monthlyPolicySaving=false;}}
