  function notificationRulesHtml(){var rows=notificationRuleRows();if(!rows.length)return '<div class="phfck-notification-empty"><b>Không có quy tắc phù hợp</b><p>Thử đổi từ khóa hoặc nhóm sự kiện.</p></div>';return '<div class="phfck-notification-rule-list">'+rows.map(function(rule){var event=notificationEvent(rule.event);return '<article class="'+(rule.mandatory?'is-mandatory':'')+'"><div class="phfck-notification-rule-main"><span class="is-'+esc(event.category)+'">'+esc(notificationCategoryLabel(event.category))+'</span><div><b>'+esc(event.name)+'</b><small>'+esc(rule.recipient)+' · '+esc(rule.timing)+'</small></div></div><div><small>Nhắc lại</small><b>'+esc(rule.repeat)+'</b></div><div><small>Ngừng khi</small><b>'+esc(rule.stop)+'</b></div><div class="phfck-notification-rule-state"><span class="is-'+esc(rule.priority.toLowerCase())+'">'+esc(rule.priority)+'</span><strong>'+(rule.mandatory?'Bắt buộc · Luôn áp dụng':(rule.active?'Đang áp dụng':'Đã ngừng'))+'</strong></div><button type="button" data-phfck-notification-edit="'+esc(rule.id)+'">Xem / sửa</button></article>';}).join('')+'</div>';}
  function notificationRuleModalHtml(rule){rule=rule||{id:'',event:'VIOLATION_CREATED',recipient:'Nhân viên liên quan',timing:'Gửi ngay',repeat:'Không nhắc lại',stop:'Khi công việc hoàn tất',priority:'Trung bình',active:true,mandatory:false};var event=notificationEvent(rule.event),recipients=['Nhân viên liên quan','Người ghi nhận lỗi','Quản lý trực tiếp','Người được phân quyền thẩm định','Admin Checklist','Người có quyền được thay đổi'],timings=['Gửi ngay','Trước hạn 1 ngày','Trước hạn 2 ngày','Khi đã quá hạn 1 ngày'],repeats=['Không nhắc lại','Nhắc mỗi ngày · tối đa 2 lần','Nhắc mỗi ngày · tối đa 3 lần'],priorities=['Trung bình','Cao','Khẩn'];function options(rows,current){return rows.map(function(x){return '<option value="'+esc(x)+'"'+(x===current?' selected':'')+'>'+esc(x)+'</option>';}).join('');}return '<div class="phfck-modal-layer phfck-edit-layer" data-phfck-submodal><div class="phfck-modal phfck-notification-modal" role="dialog" aria-modal="true"><div class="phfck-modal-head"><div><small>QUY TẮC THÔNG BÁO</small><h2>'+(rule.id?'Xem và điều chỉnh':'Tạo từ sự kiện có sẵn')+'</h2></div><button type="button" data-phfck-close-submodal>×</button></div><div class="phfck-modal-body"><div class="phfck-notification-draft-note"><b>Cấu hình dữ liệu thật</b><span>Khi bấm Lưu, quy tắc được ghi lại và áp dụng cho hệ thống.</span></div><div class="phfck-notification-form"><label class="is-wide"><span>Sự kiện *</span><select data-phfck-notification-field="event"'+(rule.mandatory?' disabled':'')+'>'+notificationEventCatalog().map(function(x){return '<option value="'+x.code+'"'+(x.code===rule.event?' selected':'')+'>'+esc(notificationCategoryLabel(x.category)+' · '+x.name)+'</option>';}).join('')+'</select>'+(rule.mandatory?'<small>Sự kiện hệ thống bắt buộc không được đổi loại.</small>':'')+'</label><label><span>Người nhận *</span><select data-phfck-notification-field="recipient">'+options(recipients,rule.recipient)+'</select></label><label><span>Thời điểm gửi *</span><select data-phfck-notification-field="timing">'+options(timings,rule.timing)+'</select></label><label><span>Nhắc lại</span><select data-phfck-notification-field="repeat">'+options(repeats,rule.repeat)+'</select></label><label><span>Mức độ</span><select data-phfck-notification-field="priority">'+options(priorities,rule.priority)+'</select></label><label class="is-wide"><span>Ngừng nhắc khi *</span><input value="'+esc(rule.stop)+'" data-phfck-notification-field="stop"></label><label class="is-wide"><span>Nội dung thông báo</span><textarea rows="3" data-phfck-notification-field="template">'+esc(rule.template||event.template)+'</textarea><small>Biến được phép: {TEN_NHAN_VIEN}, {KY_DANH_GIA}, {HAN_XU_LY}.</small></label></div><div class="phfck-notification-access"><b>Quyền quản trị</b><p>Mọi người chỉ xem thông báo của mình. Chỉ Admin Checklist được cấu hình quy tắc; backend kiểm tra lại quyền khi lưu.</p></div></div><div class="phfck-modal-foot"><button type="button" class="phfck-secondary" data-phfck-close-submodal>Hủy</button><button type="button" class="phfck-primary" data-phfck-notification-draft-save="'+esc(rule.id)+'">Lưu quy tắc</button></div></div></div>';}
  async function saveNotificationDraft(root,modal,id){function field(name){var el=modal.querySelector('[data-phfck-notification-field="'+name+'"]');return el?normalizeText(el.value):'';}var rules=ensureNotificationDraftRules(),existing=rules.find(function(x){return x.id===id;}),event=field('event');var next={id:id||'',event:event,recipient:field('recipient'),timing:field('timing'),repeat:field('repeat'),stop:field('stop'),priority:field('priority'),template:field('template'),active:true,mandatory:existing?existing.mandatory:notificationEvent(event).category==='system'};if(!next.stop){checklistToast('warning','Chưa thể lưu','Vui lòng nhập điều kiện ngừng nhắc.');return;}var button=modal.querySelector('[data-phfck-notification-draft-save]');if(button){button.disabled=true;button.textContent='Đang lưu…';}try{var data=await checklistNotificationRequest('saveChecklistNotificationRule',{rule:{eventCode:next.event,recipient:next.recipient,timing:next.timing,repeatRule:next.repeat,stopCondition:next.stop,priority:next.priority,template:next.template,isActive:next.active}});next.id=data.rule&&data.rule.id||next.id;next.mandatory=!!(data.rule&&data.rule.isMandatory);if(existing)Object.assign(existing,next);else rules.push(next);notificationUiState.ready=true;modal.remove();syncChecklistModalScrollLock();var workspace=root.querySelector('[data-phfck-workspace]');if(workspace)workspace.innerHTML=settingsHtml();checklistToast('success','Đã lưu cấu hình','Quy tắc đã được lưu an toàn.');}catch(error){if(button){button.disabled=false;button.textContent='Lưu quy tắc';}checklistToast('error','Chưa thể lưu cấu hình',error&&error.message||'Vui lòng thử lại.',true);}}
  function notificationsSettingsHtml(){var rules=ensureNotificationDraftRules(),active=rules.filter(function(x){return x.active;}).length,mandatory=rules.filter(function(x){return x.mandatory;}).length;return '<section class="phfck-settings-grid phfck-notification-settings"><article class="phfck-panel phfck-settings-card phfck-settings-wide"><div class="phfck-panel-head"><div><small>ĐIỀU HÀNH THÔNG BÁO</small><h3>Nhắc đúng người, đúng việc</h3></div><button type="button" class="phfck-primary" data-phfck-notification-add '+(notificationUiState.ready?'':'disabled')+'>＋ Tạo quy tắc</button></div><div class="phfck-notification-kpis"><div><span>Tổng quy tắc</span><b>'+rules.length+'</b></div><div><span>Đang áp dụng</span><b>'+active+'</b></div><div><span>Bắt buộc</span><b>'+mandatory+'</b></div><div><span>Vị trí nhận</span><b>Chuông cạnh tên</b></div></div><div class="phfck-notification-toolbar"><div class="phfck-search"><span>⌕</span><input type="search" placeholder="Tìm sự kiện, người nhận hoặc thời điểm" value="'+esc(notificationUiState.query)+'" data-phfck-notification-search></div><select data-phfck-notification-category><option value="all">Tất cả nhóm</option>'+['violations','monthly','operation','system'].map(function(x){return '<option value="'+x+'"'+(notificationUiState.category===x?' selected':'')+'>'+notificationCategoryLabel(x)+'</option>';}).join('')+'</select></div><div data-phfck-notification-rules>'+notificationRulesHtml()+'</div></article><article class="phfck-panel phfck-settings-card"><div class="phfck-panel-head"><div><small>NGUYÊN TẮC GỬI</small><h3>Không tạo thêm việc rác</h3></div></div>'+permissionSafetyRule('Đọc không đồng nghĩa đã xử lý','Việc chỉ đóng khi nghiệp vụ thực sự hoàn tất.')+permissionSafetyRule('Một sự việc, một thông báo hoạt động','Nhắc lại chỉ cập nhật lần nhắc, không sinh dòng trùng.')+permissionSafetyRule('Thông báo phải mở đúng hồ sơ','Không dẫn người dùng về trang tổng quan chung.')+'</article><article class="phfck-panel phfck-settings-card"><div class="phfck-panel-head"><div><small>PHÂN QUYỀN CẤU HÌNH</small><h3>Ai được quản trị thông báo</h3></div></div><div class="phfck-notification-permissions"><div><span>01</span><p><b>Mọi người dùng</b><small>Chỉ xem và đánh dấu thông báo của chính mình.</small></p></div><div><span>02</span><p><b>Người có quyền báo cáo</b><small>Xem thống kê tổng hợp, không đọc nội dung riêng của người khác.</small></p></div><div><span>03</span><p><b>Admin Checklist</b><small>Tạo, sửa, ngừng quy tắc và xem lịch sử cấu hình.</small></p></div></div></article></section>';}
  function auditSettingsHtml(){return '<section class="phfck-settings-grid"><article class="phfck-panel phfck-settings-card"><div class="phfck-panel-head"><div><small>NHẬT KÝ NGHIỆP VỤ</small><h3>Phải lưu trước–sau</h3></div></div>'+settingSwitch('Phân công và đổi mẫu','Lưu người đổi, thời gian, lý do và khoảng hiệu lực.',true,true)+settingSwitch('Điều chỉnh/hủy lỗi','Lưu giá trị cũ, mới và người phê duyệt.',true,true)+settingSwitch('Sửa sau khóa','Bắt buộc lý do và không được xóa lịch sử.',true,true)+'</article><article class="phfck-panel phfck-settings-card"><div class="phfck-panel-head"><div><small>XÓA & KHÔI PHỤC</small><h3>An toàn dữ liệu</h3></div></div>'+settingSwitch('Soft delete mặc định','Dữ liệu đã dùng báo cáo không xóa cứng trực tiếp.',true,true)+settingSwitch('Thùng rác có kiểm soát','Khôi phục hoặc xóa vĩnh viễn chỉ dành cho Admin được cấp quyền.',true,true)+'</article><article class="phfck-panel phfck-settings-card phfck-settings-wide"><div class="phfck-panel-head"><div><small>BẢO MẬT KHI NỐI DỮ LIỆU</small><h3>Điều kiện trước production</h3></div></div><div class="phfck-audit-checks"><div><span>✓</span><p><b>RLS/revoke ngay từ đầu</b><small>Mọi bảng checklist_* và Storage phải được bảo vệ server-side.</small></p></div><div><span>✓</span><p><b>Health kiểm tra DB thật</b><small>Lỗi kết nối phải trả 503, không báo xanh giả.</small></p></div><div><span>✓</span><p><b>Smoke test route và quyền</b><small>Cập nhật đồng thời khi thêm API hoặc route mới.</small></p></div><div><span>✓</span><p><b>Release sạch</b><small>Không chứa .env, private, backup hoặc node_modules.</small></p></div></div></article></section>';}
