      var marketingKpiOpen=e.target.closest('[data-phfck-marketing-kpi-open]');if(marketingKpiOpen){e.preventDefault();marketingKpiUiState.open=true;marketingKpiUiState.period=marketingKpiOpen.getAttribute('data-phfck-marketing-kpi-period')||marketingKpiPeriodValue();marketingKpiUiState.templateId='tbp-mkt-1.0';marketingKpiUiState.reason='';appendSubmodal(root,marketingKpiModalHtml());loadMarketingKpi(root);return;}
