      var marketingKpiReload=e.target.closest('[data-phfck-marketing-kpi-reload]');if(marketingKpiReload){e.preventDefault();loadMarketingKpi(root);return;}
      var marketingKpiSave=e.target.closest('[data-phfck-marketing-kpi-save]');if(marketingKpiSave&&!marketingKpiSave.disabled){e.preventDefault();saveMarketingKpi(root);return;}
      var violationRetry=e.target.closest('[data-phfck-violation-retry]');
      if(violationRetry){e.preventDefault();showViolationLoading(root,false);initializeViolationsView(root,true);return;}
