    var latestPeriod=periods.sort().pop()||todayIso().slice(0,7),reviewForms=forms.filter(function(f){return (f.period_month||'')===latestPeriod;}),query=normalizeMatchText(managerPeopleUiState.query||''),department=normalizeMatchText(managerPeopleUiState.department||''),assignedByCode={},myFormByCode={};
    reviewForms.forEach(function(f){var code=normalizeText(f.employee_code||f.employeeCode||'').toUpperCase();if(code&&!assignedByCode[code])assignedByCode[code]=f;});
    if(myForm&&(myForm.period_month||'')===latestPeriod){var myCode=normalizeText(myForm.employee_code||myForm.employeeCode||'').toUpperCase();if(myCode)myFormByCode[myCode]=myForm;}
